export interface ConnectorConfig {
  githubOwner: string
  githubRepo: string
  zendeskSubdomain: string
  githubToken: string
  zendeskToken: string
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  detail: {
    id: string
    subject: string
    description: string
    [key: string]: unknown
  }
  [key: string]: unknown
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

async function postJson<T>(
  fetchFn: typeof fetch,
  url: string,
  body: unknown,
  token: string,
): Promise<T> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Request failed: ${response.status} ${response.statusText} for ${url}`)
  }

  return response.json() as Promise<T>
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description')
  }
  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id')
  }

  const { subject, description, id: ticketId } = payload.detail

  const githubIssueResponse = await postJson<{
    number: number
    html_url: string
  }>(
    fetchFn,
    `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`,
    { title: subject, body: description },
    config.githubToken,
  )

  const commentBody = `GitHub issue created: ${githubIssueResponse.html_url}`

  const zendeskCommentResponse = await postJson<{
    comment: { id: number }
  }>(
    fetchFn,
    `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`,
    { comment: { body: commentBody } },
    config.zendeskToken,
  )

  return {
    githubIssueNumber: githubIssueResponse.number,
    githubIssueUrl: githubIssueResponse.html_url,
    zendeskCommentId: zendeskCommentResponse.comment.id,
  }
}

