describe('handle', () => {
  let baseConfig: ConnectorConfig
  let basePayload: ZendeskTicketCreatedPayload

  beforeEach(() => {
    baseConfig = {
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      zendeskSubdomain: 'example',
      githubToken: 'gh-token',
      zendeskToken: 'zen-token',
    }
    basePayload = {
      detail: {
        id: '14038',
        subject: 'Test ticket',
        description: 'Test description',
      },
    }
  })

  it('creates GitHub issue and posts Zendesk comment on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/octocat/Hello-World/issues' && req.method === 'POST') {
        expect(req.json).toEqual({ title: 'Test ticket', body: 'Test description' })
        expect(req.headers.get('authorization')).toBe('Bearer gh-token')
        return jsonResponse({ id: 1, number: 42, html_url: 'https://github.com/octocat/Hello-World/issues/42' }, 201)
      }
      if (req.url === 'https://example.zendesk.com/api/v2/tickets/14038/comments.json' && req.method === 'POST') {
        expect(req.json).toEqual({ comment: { body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/42' } })
        expect(req.headers.get('authorization')).toBe('Bearer zen-token')
        return jsonResponse({ comment: { id: 999, body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/42', author_id: 1, created_at: '2025-01-14T20:30:00Z' } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch })

    expect(result).toEqual({
      githubIssueNumber: 42,
      githubIssueUrl: 'https://github.com/octocat/Hello-World/issues/42',
      zendeskCommentId: 999,
    })
    expect(calls).toHaveLength(2)
  })

  it('throws when detail.subject is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { detail: { id: '1', description: 'desc' } } as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.subject')
  })

  it('throws when detail.description is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { detail: { id: '1', subject: 'subj' } } as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.description')
  })

  it('throws when detail.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { detail: { subject: 'subj', description: 'desc' } } as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.id')
  })

  it('throws descriptive error on non-2xx GitHub response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ message: 'Bad credentials' }, 401))

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Request failed: 401 Unauthorized for https://api.github.com/repos/octocat/Hello-World/issues',
    )
  })

  it('throws descriptive error on non-2xx Zendesk response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/octocat/Hello-World/issues' && req.method === 'POST') {
        return jsonResponse({ id: 1, number: 42, html_url: 'https://github.com/octocat/Hello-World/issues/42' }, 201)
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Request failed: 403 Forbidden for https://example.zendesk.com/api/v2/tickets/14038/comments.json',
    )
    expect(calls).toHaveLength(2)
  })

  it('uses injected fetch instead of global fetch', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/octocat/Hello-World/issues') {
        return jsonResponse({ id: 1, number: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1' }, 201)
      }
      return jsonResponse({ comment: { id: 1 } }, 201)
    })

    await handle(basePayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(2)
  })
})

